import { useState } from "react";
import axios from "axios";

function Register() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [otp, setOtp] = useState("");
  const [step, setStep] = useState(1); // 1=send OTP, 2=verify OTP, 3=register
  const [loading, setLoading] = useState(false);

  // ================= SEND OTP =================
  const sendOtp = async () => {
    setLoading(true);
    try {
      await axios.post("http://localhost:5000/api/auth/send-otp", {
        email,
      });

      alert("OTP sent to email 📩");
      setStep(2);
    } catch (err) {
      alert("OTP send failed ❌");
    }
    setLoading(false);
  };

  // ================= VERIFY OTP =================
  const verifyOtp = async () => {
    setLoading(true);
    try {
      await axios.post("http://localhost:5000/api/auth/verify-otp", {
        email,
        otp,
      });

      alert("OTP verified ✅");
      setStep(3);
    } catch (err) {
      alert("Invalid OTP ❌");
    }
    setLoading(false);
  };

  // ================= REGISTER =================
  const registerUser = async () => {
    setLoading(true);
    try {
      await axios.post("http://localhost:5000/api/auth/register", {
        name,
        email,
        password,
      });

      alert("Registered Successfully 🚀");
      window.location.href = "/login";
    } catch (err) {
      alert("Register failed ❌");
    }
    setLoading(false);
  };

  return (
    <div style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>Create Account 🚀</h2>
        <p style={styles.subtitle}>Register with OTP verification</p>

        {/* NAME */}
        <input
          style={styles.input}
          placeholder="Full Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />

        {/* EMAIL */}
        <input
          style={styles.input}
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />

        {/* PASSWORD */}
        <input
          style={styles.input}
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />

        {/* STEP 1: SEND OTP */}
        {step === 1 && (
          <button style={styles.button} onClick={sendOtp} disabled={loading}>
            {loading ? "Sending OTP..." : "Send OTP"}
          </button>
        )}

        {/* STEP 2: VERIFY OTP */}
        {step === 2 && (
          <>
            <input
              style={styles.input}
              placeholder="Enter OTP"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
            />
            <button style={styles.button} onClick={verifyOtp} disabled={loading}>
              {loading ? "Verifying..." : "Verify OTP"}
            </button>
          </>
        )}

        {/* STEP 3: REGISTER */}
        {step === 3 && (
          <button style={styles.button} onClick={registerUser} disabled={loading}>
            {loading ? "Registering..." : "Register"}
          </button>
        )}

        <p style={styles.footer}>
          Already have account? <span style={{ color: "#6c5ce7" }}>Login</span>
        </p>
      </div>
    </div>
  );
}

// ================= STYLES =================
const styles = {
  container: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "linear-gradient(135deg, #00d2d3, #6c5ce7)",
    fontFamily: "Arial",
  },
  card: {
    background: "#fff",
    padding: "40px",
    borderRadius: "15px",
    width: "380px",
    boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
    textAlign: "center",
  },
  title: {
    marginBottom: "5px",
    color: "#2d3436",
  },
  subtitle: {
    marginBottom: "20px",
    color: "#636e72",
    fontSize: "14px",
  },
  input: {
    width: "100%",
    padding: "12px",
    marginBottom: "10px",
    borderRadius: "8px",
    border: "1px solid #ddd",
    outline: "none",
    fontSize: "14px",
  },
  button: {
    width: "100%",
    padding: "12px",
    borderRadius: "8px",
    border: "none",
    background: "linear-gradient(135deg, #6c5ce7, #00d2d3)",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
    marginTop: "10px",
  },
  footer: {
    marginTop: "15px",
    fontSize: "13px",
    color: "#636e72",
  },
};

export default Register;
